import { NextResponse } from 'next/server';
import { requireSession } from '@/lib/auth-helpers';
import { db } from '@/db';
import { callHistory } from '@/db/schema';
import { and, eq, or } from 'drizzle-orm';
import { AccessToken } from 'livekit-server-sdk';
import { env } from '@/lib/env';

export async function GET(
  request: Request,
  { params }: { params: Promise<{ roomName: string }> }
) {
  try {
    const session = await requireSession();
    const userId = session.user.id;
    const { roomName } = await params;

    const call = await db.query.callHistory.findFirst({
      where: and(
        eq(callHistory.roomName, roomName),
        or(
          eq(callHistory.callerId, userId),
          eq(callHistory.calleeId, userId)
        ),
        eq(callHistory.status, 'ongoing')
      )
    });

    if (!call) {
      return NextResponse.json(
        { error: 'Call not found or already ended' },
        { status: 404 }
      );
    }

    const token = new AccessToken(
      env.LIVEKIT_API_KEY,
      env.LIVEKIT_API_SECRET,
      { identity: userId, ttl: '5m' }
    );
    token.addGrant({
      roomJoin: true,
      room: roomName,
      canPublish: true,
      canSubscribe: true
    });
    const jwt = await token.toJwt();

    if (!call.startedAt) {
      await db
        .update(callHistory)
        .set({ startedAt: new Date() })
        .where(eq(callHistory.roomName, roomName));
    }

    return NextResponse.json({ token: jwt, liveKitUrl: env.LIVEKIT_URL });
  } catch (error) {
    console.error('[GET /api/calls/token] Error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

