async function joinCall(roomName: string) {
  try {
    const res = await fetch(`/api/calls/token/${roomName}`);
    if (!res.ok) {
      const err = await res.json();
      throw new Error(err.error ?? 'Token fetch failed');
    }
    const { token, liveKitUrl } = await res.json();
    await room.connect(liveKitUrl, token);
  } catch (error) {
    console.error('Failed to join call:', error);
    await fetch(`/api/calls/${roomName}`, { method: 'DELETE' }).catch(() => {});
    toast.error('Failed to join the call');
    router.push('/messages');
  }
}
